problems.description:
Find common friends between two people using sets.

alice_friends = {"Bob", "Charlie", "Diana", "Eve"}
bob_friends = {"Alice", "Charlie", "Frank", "Diana"}

Print:
Common friends: {Charlie, Diana} (order may vary)
Only Alice's friends: {Bob, Eve}
All unique friends: {all names}

problems.solution:
alice_friends = {"Bob", "Charlie", "Diana", "Eve"}
bob_friends = {"Alice", "Charlie", "Frank", "Diana"}

print("Common friends:", alice_friends & bob_friends)
print("Only Alice's friends:", alice_friends - bob_friends)
print("All unique friends:", alice_friends | bob_friends)
